import{c as t,Q as a,j as s,m as n}from"./chunks/framework.t4rEqR7d.js";const k=JSON.parse('{"title":"VS Code Extension","description":"","frontmatter":{},"headers":[],"relativePath":"vscode.md","filePath":"vscode.md"}'),i={name:"vscode.md"};function o(d,e,l,p,h,r){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="vs-code-extension" tabindex="-1">VS Code Extension <a class="header-anchor" href="#vs-code-extension" aria-label="Permalink to &quot;VS Code Extension&quot;">​</a></h1><p>Language: <a href="/pagent/zh/vscode.html">中文</a> | English</p><p>The pagent VS Code extension adds a chat panel to VS Code. After installing the extension, you can talk to pagent from the sidebar and let it read files, run commands, call tools, and resume previous conversations in the current workspace.</p><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><p>Download the VS Code extension package from <a href="https://github.com/SyncLionPaw/pagent/releases" target="_blank" rel="noreferrer">pagent GitHub Releases</a>:</p><p>Download the file ending in <code>.vsix</code>.</p><p>Install it in VS Code:</p><ol><li>Open the <strong>Extensions</strong> panel.</li><li>Click the <code>...</code> menu in the upper-right corner of the Extensions panel.</li><li>Select <strong>Install from VSIX...</strong>.</li><li>Pick the <code>.vsix</code> file you downloaded.</li><li>Reload the VS Code window after installation. The pagent icon appears in the activity bar.</li></ol><p>You can also open the command palette and run:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extensions: Install from VSIX...</span></span></code></pre></div><p>The extension also needs the <code>pagent</code> command on your machine. Install the CLI first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pagent</span></span></code></pre></div><p>If VS Code cannot find <code>pagent</code>, set <code>pagent.command</code> to the absolute path of the executable.</p><h2 id="first-run" tabindex="-1">First Run <a class="header-anchor" href="#first-run" aria-label="Permalink to &quot;First Run&quot;">​</a></h2><p>Click the pagent icon in the activity bar and open <strong>Chat</strong>.</p><p>If no API key has been configured yet, the extension asks for:</p><ul><li>API key</li><li>model name, default: <code>deepseek-v4-flash</code></li><li>base URL, optional</li></ul><p>After saving the config, the extension writes <code>pagent.toml</code> and you can start chatting.</p><p>The <a href="/pagent/desktop.html">Desktop app</a> does <strong>not</strong> include this guided setup — configure <code>pagent.toml</code> or <code>DEEPSEEK_API_KEY</code> before chatting.</p><h2 id="files-created-by-the-extension" tabindex="-1">Files Created by the Extension <a class="header-anchor" href="#files-created-by-the-extension" aria-label="Permalink to &quot;Files Created by the Extension&quot;">​</a></h2><p>The extension uses a pagent home directory for config, conversation history, and local skills.</p><p>If the current workspace already has <code>.pagent/</code>, the extension uses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;workspace&gt;/.pagent/</span></span></code></pre></div><p>If the workspace does not have <code>.pagent/</code>, the extension uses:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.pagent/</span></span></code></pre></div><p>If you want a project to have its own config and conversation history, create <code>.pagent/</code> in the project root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .pagent</span></span></code></pre></div><p>After that, the extension uses the project-local <code>.pagent/</code>.</p><p>Common files:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.pagent/</span></span>
<span class="line"><span>├── pagent.toml          # Config: model, API key, sandbox, permissions</span></span>
<span class="line"><span>├── threads/             # Conversation history</span></span>
<span class="line"><span>│   └── thread-.../</span></span>
<span class="line"><span>│       ├── metainfo.json</span></span>
<span class="line"><span>│       └── messages.jsonl</span></span>
<span class="line"><span>└── skills/              # Optional local skills</span></span></code></pre></div><p>What these files mean:</p><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>pagent.toml</code></td><td>Model, API key, base URL, runtime mode, SSH, approval mode</td></tr><tr><td><code>threads/</code></td><td>Conversation history; each thread is a resumable conversation</td></tr><tr><td><code>metainfo.json</code></td><td>Thread title, created time, updated time, message count</td></tr><tr><td><code>messages.jsonl</code></td><td>Messages in that thread</td></tr><tr><td><code>skills/</code></td><td>Optional local skills</td></tr></tbody></table><p>Empty threads with no messages are cleaned up when the backend exits normally.</p><p>If <code>.pagent/</code> is inside a project that you commit to Git, avoid committing a <code>pagent.toml</code> that contains an API key.</p><h2 id="config-file" tabindex="-1">Config File <a class="header-anchor" href="#config-file" aria-label="Permalink to &quot;Config File&quot;">​</a></h2><p>The extension writes <code>pagent.toml</code> after the first API key setup. You can also edit it manually:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">provider</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">api_key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sk-...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;deepseek-v4-flash&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># base_url = &quot;https://...&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sandbox</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">backend = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;local&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # local | docker | podman | ssh</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">command_policy = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;workdir&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config_path = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/.ssh/config&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-remote&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">workdir = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;~/pagent&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prompt&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # prompt | auto</span></span></code></pre></div><p>You can also provide the API key with an environment variable:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> DEEPSEEK_API_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sk-...</span></span></code></pre></div><h2 id="use-the-chat" tabindex="-1">Use the Chat <a class="header-anchor" href="#use-the-chat" aria-label="Permalink to &quot;Use the Chat&quot;">​</a></h2><p>Open Chat, type in the composer, and press Enter to send. Use Shift+Enter for a new line.</p><p>The extension streams the answer as it arrives. Reasoning appears in a collapsible <code>thinking</code> panel. Tool calls appear as tool cards, which can be expanded for details.</p><h2 id="title-bar-buttons" tabindex="-1">Title Bar Buttons <a class="header-anchor" href="#title-bar-buttons" aria-label="Permalink to &quot;Title Bar Buttons&quot;">​</a></h2><p>The Chat title bar has three buttons:</p><table tabindex="0"><thead><tr><th>Button</th><th>Meaning</th></tr></thead><tbody><tr><td>Open in editor</td><td>Open a wider chat panel in the editor area</td></tr><tr><td>Resume session</td><td>Pick a previous conversation and continue it</td></tr><tr><td>New session</td><td>Start a new empty conversation</td></tr></tbody></table><h2 id="composer-buttons" tabindex="-1">Composer Buttons <a class="header-anchor" href="#composer-buttons" aria-label="Permalink to &quot;Composer Buttons&quot;">​</a></h2><p>The composer footer has:</p><table tabindex="0"><thead><tr><th>Button</th><th>Meaning</th></tr></thead><tbody><tr><td><code>/</code></td><td>Open the slash command menu</td></tr><tr><td>Runtime mode</td><td>Choose where tools run</td></tr><tr><td>Stamp</td><td>Toggle YOLO mode</td></tr><tr><td>Send</td><td>Send the current message</td></tr></tbody></table><p>YOLO mode automatically approves dangerous tool calls such as running commands. Use it only when you trust the current workspace and request.</p><h2 id="runtime-modes" tabindex="-1">Runtime Modes <a class="header-anchor" href="#runtime-modes" aria-label="Permalink to &quot;Runtime Modes&quot;">​</a></h2><p>The runtime mode controls where pagent tools run.</p><table tabindex="0"><thead><tr><th>Mode</th><th>Meaning</th></tr></thead><tbody><tr><td>Local</td><td>Run tools on the current machine</td></tr><tr><td>Docker</td><td>Run tools in a Docker container</td></tr><tr><td>Podman</td><td>Run tools in a Podman container</td></tr><tr><td>SSH</td><td>Run tools on a remote machine</td></tr></tbody></table><p>Docker and Podman appear only when the corresponding CLI exists in the VS Code host environment.</p><p>SSH mode reads <code>~/.ssh/config</code> and shows explicit <code>Host</code> aliases. Wildcard entries such as <code>Host *</code> are hidden.</p><h2 id="slash-commands" tabindex="-1">Slash Commands <a class="header-anchor" href="#slash-commands" aria-label="Permalink to &quot;Slash Commands&quot;">​</a></h2><p>Click <code>/</code>, or type <code>/</code> in the composer, to open the command menu.</p><p>Current commands:</p><table tabindex="0"><thead><tr><th>Command</th><th>Meaning</th></tr></thead><tbody><tr><td><code>/help</code></td><td>Show available commands</td></tr><tr><td><code>/skills</code></td><td>Show loaded skills</td></tr><tr><td><code>/history</code></td><td>Show conversation information</td></tr><tr><td><code>/pwd</code></td><td>Show the active pagent home / workspace context</td></tr><tr><td><code>/ls</code></td><td>List files in the current context</td></tr></tbody></table><p>Slash commands do not start a model turn and do not enter conversation history.</p><h2 id="tool-approval" tabindex="-1">Tool Approval <a class="header-anchor" href="#tool-approval" aria-label="Permalink to &quot;Tool Approval&quot;">​</a></h2><p>By default, dangerous tools pause for approval. The tool card shows approve and deny buttons.</p><p>If YOLO mode is enabled, approvals are skipped. You can also set:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">permission</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;auto&quot;</span></span></code></pre></div><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><p><strong>The pagent icon does not appear.</strong></p><p>Make sure the <code>.vsix</code> installation succeeded, then reload the VS Code window.</p><p><strong>VS Code cannot find <code>pagent</code>.</strong></p><p>Run <code>uv tool install pagent</code>. If it still cannot be found, set <code>pagent.command</code> in VS Code settings.</p><p><strong>Docker or Podman does not appear in the menu.</strong></p><p>The corresponding CLI is missing from the VS Code host environment, or it is not available in PATH.</p><p><strong>SSH hosts do not appear.</strong></p><p>Check <code>pagent.sshConfigPath</code> and make sure it contains explicit <code>Host xxx</code> entries.</p><p><strong>Where is conversation history stored?</strong></p><p>Under <code>threads/</code> in the active pagent home. In project mode this is usually <code>&lt;workspace&gt;/.pagent/threads/</code>; otherwise it is <code>~/.pagent/threads/</code>.</p>`,74)])])}const g=t(i,[["render",o]]);export{k as __pageData,g as default};
